-- exhibitions.museum_id는 애초에 text(문자열 id) 기준으로 설계됐는데, 실제 museums.id는
-- 정수(serial)라 타입이 안 맞는다. 아직 어떤 행도 museum_id를 채운 적이 없어(전부 null)
-- 안전하게 타입을 교체한다.
alter table public.exhibitions drop column museum_id;
alter table public.exhibitions add column museum_id bigint references public.museums (id);
